<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuth } from '../stores/auth'; import AuthForm from '../components/AuthForm.vue'; import AuthShell from '../components/AuthShell.vue'
const router = useRouter(); const { authenticate, state } = useAuth(); const error = ref(''); const success = ref(false)
async function register(payload: { name?: string; paternal_surname?: string; maternal_surname?: string; phone?: string; email: string; password: string }) { error.value = ''; try { await authenticate('register', { name: payload.name ?? '', paternal_surname: payload.paternal_surname ?? '', maternal_surname: payload.maternal_surname?.trim() || undefined, phone: payload.phone ?? '', email: payload.email, password: payload.password } as Record<string, string>); success.value = true } catch (e: any) { const status = e.response?.status; error.value = status === 409 ? 'Ya existe una cuenta asociada a este correo electrónico' : status === 422 ? 'Revisa los datos proporcionados e inténtalo nuevamente.' : status ? 'No fue posible crear la cuenta. Inténtalo nuevamente.' : 'No fue posible conectar con el servidor. Inténtalo nuevamente.' } }
function afterSuccess(open: boolean) { if (!open) router.push('/dashboard') }
</script>
<template><AuthShell wide eyebrow="COMIENZA AQUÍ" title="Crear cuenta" subtitle="Registra al personal que tendrá acceso al sistema de administración del taller. Los campos marcados con * son obligatorios."><v-alert v-if="error" icon="mdi-alert-circle-outline" variant="tonal" density="comfortable" class="auth-error-alert mb-5" closable @click:close="error = ''">{{ error }}</v-alert><AuthForm mode="register" :loading="state.loading" @submit="register" /><p class="text-center text-caption text-medium-emphasis mt-6">¿Ya tienes una cuenta? <router-link class="small-link" to="/login">Iniciar sesión</router-link></p></AuthShell><v-snackbar v-model="success" color="success" location="top" :timeout="3500" @update:model-value="afterSuccess"><v-icon icon="mdi-check-circle-outline" class="mr-2" />La cuenta ha sido creada correctamente.</v-snackbar></template>
<style scoped>.small-link { color:#3364a2;font-weight:700;text-decoration:none }.small-link:hover{color:#3867de;text-decoration:underline}</style>
